// src/app/api/anime/anilist/route.ts
import { NextRequest, NextResponse } from 'next/server';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const ANILIST_GRAPHQL_ENDPOINT = 'https://graphql.anilist.co';

let nodeDispatcher: any = null;
try {
  const dns = require('node:dns');
  const { Agent } = require('undici');
  const resolver = new dns.promises.Resolver();
  resolver.setServers(['8.8.8.8', '1.1.1.1', '8.8.4.4', '1.0.0.1']);
  nodeDispatcher = new Agent({
    connect: {
      lookup: (hostname: string, options: any, callback: any) => {
        if (typeof options === 'function') {
          callback = options;
          options = {};
        }
        resolver.resolve4(hostname)
          .then((ips: string[]) => {
            if (options && options.all) {
              callback(null, ips.map(ip => ({ address: ip, family: 4 })));
            } else {
              callback(null, ips[0], 4);
            }
          })
          .catch((err: any) => dns.lookup(hostname, options, callback));
      }
    }
  });
} catch {}

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { query, variables } = body;

    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 10000);

    const fetchOptions: any = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      },
      body: JSON.stringify({ query, variables }),
      signal: controller.signal,
    };

    if (nodeDispatcher) {
      fetchOptions.dispatcher = nodeDispatcher;
    }

    const res = await fetch(ANILIST_GRAPHQL_ENDPOINT, fetchOptions);
    clearTimeout(timer);

    const json = await res.json();
    return NextResponse.json(json, { status: res.status });
  } catch (error: any) {
    return NextResponse.json(
      { errors: [{ message: error.message || 'AniList Proxy Request Failed' }] },
      { status: 500 }
    );
  }
}
